describe('Success Toast Notification on Record Save', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display success toast notification after saving a record successfully', () => {
    // Intercept the API call to save the record
    cy.intercept('POST', '/api/records/save').as('saveRecord');

    // Get the record form
    cy.get('[data-testid="record-form"]').should('be.visible');

    // Fill in the form with valid data
    cy.get('[data-testid="record-name-input"]').type('Sample Record');
    cy.get('[data-testid="record-description-input"]').type('This is a sample record description');

    // Save the record
    cy.get('[data-testid="save-button"]').click();

    // Wait for the API call to complete
    cy.wait('@saveRecord');

    // Verify success toast notification appears
    cy.get('[data-testid="toast-container"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Record saved successfully');

    // Verify toast has a close button
    cy.get('[data-testid="success-toast-close-btn"]').should('be.visible');

    // Verify toast is removed after clicking close
    cy.get('[data-testid="success-toast-close-btn"]').click();
    cy.get('[data-testid="toast-container"]').should('not.exist');

    // Verify record is listed in the table
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').should('contain', 'Sample Record');
  });

  it('should not display success toast notification when record save fails', () => {
    // Intercept the API call to save the record with an error
    cy.intercept('POST', '/api/records/save', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('saveRecordError');

    // Get the record form
    cy.get('[data-testid="record-form"]').should('be.visible');

    // Fill in the form with valid data
    cy.get('[data-testid="record-name-input"]').type('Test Record');
    cy.get('[data-testid="record-description-input"]').type('This is a test record description');

    // Save the record
    cy.get('[data-testid="save-button"]').click();

    // Wait for the API call to complete
    cy.wait('@saveRecordError');

    // Verify error toast notification appears instead
    cy.get('[data-testid="toast-container"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to save record');

    // Verify error toast has a close button
    cy.get('[data-testid="error-toast-close-btn"]').should('be.visible');

    // Verify toast is removed after clicking close
    cy.get('[data-testid="error-toast-close-btn"]').click();
    cy.get('[data-testid="toast-container"]').should('not.exist');

    // Verify record is not listed in the table
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').should('not.exist');
  });
});
